function path(x,y,rx,ry){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2)}
function drawGround(){const z=zones[data.zone];let bg=ctx.createRadialGradient(W*.5,H*.53,10,W*.5,H*.53,Math.max(W,H)*.65);bg.addColorStop(0,z.ground);bg.addColorStop(.7,'#101825');bg.addColorStop(1,'#080d17');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
// Distant rift halo
ctx.save();ctx.translate(W/2,H*.54);ctx.scale(1,.56);let pulse=1+Math.sin(elapsed*1.1)*.025;ctx.rotate(elapsed*.025);ctx.strokeStyle=z.glow+'18';ctx.lineWidth=1;for(let i=0;i<4;i++){ctx.beginPath();ctx.arc(0,0,(85+i*33)*pulse,0,Math.PI*2);ctx.stroke()}ctx.restore();
// Perspective floor rings and fine grid
ctx.save();ctx.translate(W*.5,H*.56);ctx.scale(1,.46);for(let r=1;r<10;r++){ctx.beginPath();ctx.arc(0,0,r*54,0,Math.PI*2);ctx.strokeStyle=r%3===0?z.glow+'19':'#a9bdd40b';ctx.lineWidth=r%3===0?1.2:1;ctx.stroke()}for(let i=0;i<24;i++){let a=i*Math.PI/12;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(a)*620,Math.sin(a)*620);ctx.strokeStyle='#acc3e10a';ctx.stroke()}ctx.restore();
// floating embers
for(let i=0;i<36;i++){let x=(i*173+elapsed*(i%2?7:-4))%W,y=(i*97+elapsed*(i%3?11:5))%(H*.78);ctx.globalAlpha=.12+((i*37)%70)/200;ctx.fillStyle=i%4?z.glow:'#f5d894';ctx.beginPath();ctx.arc(x,y,1+(i%3)*.45,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function drawShadow(x,y,r){ctx.save();ctx.translate(x,y+5);ctx.scale(1,.42);let g=ctx.createRadialGradient(0,0,1,0,0,r*1.5);g.addColorStop(0,'#0009');g.addColorStop(1,'#0000');ctx.fillStyle=g;path(0,0,r*1.5,r*.9);ctx.fill();ctx.restore()}
function drawEnemy(e){let z=zones[data.zone],bob=Math.sin(e.phase)*2,scale=e.z;ctx.save();ctx.translate(e.x,e.y+bob);drawShadow(0,0,e.r);ctx.scale(scale,scale);let r=e.r,c=e.boss?'#cf678b':data.zone===1?'#8f79d2':data.zone===2?'#e77b5d':'#65b9a2';
// body orb
let g=ctx.createRadialGradient(-r*.34,-r*.4,2,0,0,r*1.3);g.addColorStop(0,'#f2d9ff');g.addColorStop(.18,c);g.addColorStop(1,'#152033');ctx.fillStyle=g;path(0,0,r,r*.87);ctx.fill();ctx.strokeStyle=e.boss?'#ffbf90':'#c3f6eb66';ctx.lineWidth=e.boss?2:1;ctx.stroke();
// horns / fins
ctx.fillStyle=c;for(let s of [-1,1]){ctx.beginPath();ctx.moveTo(s*r*.45,-r*.42);ctx.lineTo(s*r*.88,-r*1.25);ctx.lineTo(s*r*.19,-r*.68);ctx.closePath();ctx.fill()}
ctx.fillStyle='#ffecb1';for(let s of [-1,1]){ctx.beginPath();ctx.ellipse(s*r*.32,-r*.08,r*.13,r*.17,0,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#311f38';ctx.beginPath();ctx.ellipse(0,r*.3,r*.3,r*.1,0,0,Math.PI*2);ctx.fill();
// health bar
ctx.fillStyle='#070d18c9';ctx.fillRect(-r,-r*1.55,r*2,3);ctx.fillStyle=e.boss?'#ff7388':z.glow;ctx.fillRect(-r,-r*1.55,r*2*clamp(e.hp/e.max,0,1),3);if(e.boss){ctx.fillStyle='#ffd2bf';ctx.font='800 8px system-ui';ctx.textAlign='center';ctx.fillText('RIFT TITAN',0,-r*1.8)}ctx.restore()}
function drawHero(){let x=hero.x,y=hero.y+Math.sin(elapsed*2)*1.5;drawShadow(x,y,21);ctx.save();ctx.translate(x,y);let flash=hero.hitFlash>0;ctx.shadowColor=flash?'#ff7188':'#68f0e2';ctx.shadowBlur=flash?24:16;
// cape
ctx.fillStyle='#553e87';ctx.beginPath();ctx.moveTo(-8,-5);ctx.quadraticCurveTo(-26,12,-16,28);ctx.lineTo(1,17);ctx.lineTo(11,28);ctx.quadraticCurveTo(22,4,8,-8);ctx.closePath();ctx.fill();
// legs and torso
ctx.shadowBlur=0;ctx.fillStyle='#263a59';ctx.beginPath();ctx.roundRect(-10,3,8,15,4);ctx.roundRect(2,3,8,15,4);ctx.fill();let g=ctx.createLinearGradient(-12,-15,12,12);g.addColorStop(0,flash?'#ffb0ba':'#a4fff3');g.addColorStop(.5,'#4fc4bc');g.addColorStop(1,'#283e62');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-12,-8);ctx.quadraticCurveTo(0,-16,12,-8);ctx.lineTo(10,9);ctx.quadraticCurveTo(0,15,-10,9);ctx.closePath();ctx.fill();
// head
ctx.fillStyle='#d9f4e9';path(0,-16,7.3,8);ctx.fill();ctx.fillStyle='#182a42';ctx.beginPath();ctx.moveTo(-8,-18);ctx.lineTo(-2,-28);ctx.lineTo(0,-18);ctx.lineTo(6,-26);ctx.lineTo(8,-16);ctx.closePath();ctx.fill();ctx.fillStyle='#69f4e0';ctx.fillRect(2,-17,3,2);
// blade
ctx.save();ctx.rotate(-.43+Math.sin(elapsed*5)*.05);ctx.strokeStyle='#a5fff0';ctx.lineWidth=3;ctx.shadowColor='#69f0e2';ctx.shadowBlur=10;ctx.beginPath();ctx.moveTo(10,-1);ctx.lineTo(20,-17);ctx.stroke();ctx.restore();
// ground sigil
ctx.globalAlpha=.5+Math.sin(elapsed*3)*.12;ctx.strokeStyle='#69f0e277';ctx.lineWidth=1;path(0,14,20,7);ctx.stroke();ctx.restore()}
function drawHook(){if(!hero.hook)return;const h=hero.hook,e=h.target;ctx.save();ctx.lineCap='round';ctx.shadowBlur=12;ctx.shadowColor='#6df2e8';let g=ctx.createLinearGradient(hero.x,hero.y,e.x,e.y);g.addColorStop(0,'#d7fff1');g.addColorStop(.35,'#67f0df');g.addColorStop(1,'#a98cff');ctx.strokeStyle=g;ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(hero.x,hero.y-8);ctx.quadraticCurveTo((hero.x+e.x)/2+(e.y-hero.y)*.13,(hero.y+e.y)/2-(e.x-hero.x)*.13,e.x,e.y);ctx.stroke();ctx.translate(e.x,e.y);ctx.rotate(elapsed*8);ctx.strokeStyle='#dcfff7';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.rotate(Math.PI*2/3);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-9);ctx.lineTo(4,-5);ctx.stroke()}ctx.restore()}
function draw(){ctx.save();if(shake)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawGround();for(const e of enemies)if(!e.dead)drawEnemy(e);drawHook();drawHero();for(const p of particles){ctx.globalAlpha=clamp(p.life*1.7,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(const f of floats){ctx.globalAlpha=clamp(f.life,0,1);ctx.fillStyle=f.color;ctx.font='900 10px system-ui';ctx.textAlign='center';ctx.shadowColor='#07101c';ctx.shadowBlur=4;ctx.fillText(f.text,f.x,f.y)}ctx.globalAlpha=1;ctx.restore()}
function updateUI(){ $('souls').textContent=compact(data.souls);$('shards').textContent=compact(data.shards);$('level').textContent=data.level;$('zoneName').textContent=zones[data.zone].name;$('zoneStage').textContent=`ZONE ${String(data.zone+1).padStart(2,'0')} · WAVE ${data.wave}`;$('healthFill').style.width=`${clamp(hero.hp/stat('health')*100,0,100)}%`;$('healthText').textContent=`${Math.ceil(hero.hp)} / ${stat('health')}`;$('regenText').textContent=`+${stat('regen').toFixed(1)} /s`;$('attackReadout').textContent=Math.round(stat('attack'));$('enemyCount').textContent=enemies.filter(e=>!e.dead).length;$('waveLabel').innerHTML=`WAVE ${data.wave} <span style="color:#647590">—</span> RIFT ACTIVITY`;$('waveFill').style.width=`${(data.kills%12)/12*100}%`;$('autoState').textContent=data.auto?'ON':'OFF';$('autoDevour').textContent=data.autoDevour?'ON':'OFF';$('autoBtn').classList.toggle('active',data.auto);let boss=enemies.find(e=>e.boss&&!e.dead);if(boss){$('bossbar').classList.add('show');$('bossFill').style.width=`${clamp(boss.hp/boss.max*100,0,100)}%`;$('bossHealthText').textContent=`${Math.ceil(boss.hp/boss.max*100)}%`}else $('bossbar').classList.remove('show');$('burstBtn').querySelector('.sub').textContent=hero.burst>0?`COOLDOWN · ${hero.burst.toFixed(1)}s`:'READY · SPACE'}
function compact(n){return n>=10000?(n/1000).toFixed(1)+'k':Math.floor(n).toLocaleString()}
function loop(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);

