requestAnimationFrame(loop);
function prices(k){let n=data.upgrade[k]||0;return Math.floor(({attack:24,speed:30,health:22,crit:35,regen:27,armor:31})[k]*Math.pow(1.48,n))}
const upgradeInfo={attack:['⚔','RIFT EDGE','Attack damage +4','attack'],speed:['➶','QUICKENING','Hook speed +14%','speed'],health:['♥','VITAL CORE','Max health +24','health'],crit:['✹','FATAL THREAD','Critical chance +3%','crit'],regen:['✚','SOUL MENDING','Health regen +0.45/s','regen'],armor:['⬡','WRAITHSKIN','Armor +2','armor']};
function openPanel(which){selectedPanel=which;$('shade').classList.add('open');renderPanel()}
function renderPanel(){let title=$('panelTitle'),sub=$('panelSub'),content=$('panelContent');content.innerHTML='';
if(selectedPanel==='upgrades'){title.textContent='PERMANENT EVOLUTION';sub.textContent='Every consumed soul carries your power forward.';let chips=document.createElement('div');chips.className='statsline';chips.innerHTML=`<div class="stat-chip">LEVEL <b>${data.level}</b></div><div class="stat-chip">ATK <b>${Math.round(stat('attack'))}</b></div><div class="stat-chip">CRIT <b>${stat('crit')}%</b></div><div class="stat-chip">REGEN <b>${stat('regen').toFixed(1)}/s</b></div>`;content.append(chips);let cards=document.createElement('div');cards.className='cards';Object.entries(upgradeInfo).forEach(([k,v])=>{let cost=prices(k),b=document.createElement('button');b.className='upgrade';b.disabled=data.souls<cost;b.innerHTML=`<span class="upicon">${v[0]}</span><span class="cost">◈ ${cost}</span><h3>${v[1]} · ${data.upgrade[k]}</h3><p>${v[2]}<br><span style="color:#66e8d9">Next: ${v[3]==='attack'?`+${Math.round(4)} ATK`:v[3]==='speed'?'+14% speed':v[3]==='health'?'+24 HP':v[3]==='crit'?'+3% crit':v[3]==='regen'?'+0.45 regen':'+2 armor'}</span></p>`;b.onclick=()=>{if(data.souls<cost)return;data.souls-=cost;data.upgrade[k]++;if(k==='health')hero.hp=Math.min(stat('health'),hero.hp+24);toast(`${v[1]} UPGRADED`);save();renderPanel()};cards.append(b)});content.append(cards);}
